import { BasicContainer } from 'components';

import { EmptySection } from '../BrandPowerDrivers/EmptySection';

interface DriversSectionProps {
  title: string;
  tooltip?: string;
  measure?: string;
}

export const DriversSection: React.FC<DriversSectionProps> = ({
  title,
  tooltip,
  measure,
}) => {
  return (
    <BasicContainer
      header={{
        title,
        tooltip,
        titleSize: 'H4',
        measure,
      }}
      layout={{
        border: 'small',
        borderRadius: 'large',
        shadow: 'small',
        bodyPadding: true,
        bottomSeparator: 'border',
      }}
      fullWidth
    >
      <EmptySection />
    </BasicContainer>
  );
};
